package com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.errors;

/**
 * ProtoException wraps validation and runtime errors with gRPC status codes. This exception follows
 * the Google RPC error model and can be converted to a protobuf Error message.
 *
 * <p>See https://cloud.google.com/apis/design/errors for more information. Generated by tacplus
 */
public class ProtoException extends RuntimeException {

  private final int code;

  // gRPC status codes (from io.grpc.Status.Code)
  public static final int INVALID_ARGUMENT = 3;
  public static final int NOT_FOUND = 5;
  public static final int DEADLINE_EXCEEDED = 4;
  public static final int UNAUTHENTICATED = 16;
  public static final int INTERNAL = 13;
  public static final int CANCELLED = 1;
  public static final int UNKNOWN = 2;
  public static final int PERMISSION_DENIED = 7;
  public static final int ALREADY_EXISTS = 6;
  public static final int RESOURCE_EXHAUSTED = 8;
  public static final int FAILED_PRECONDITION = 9;
  public static final int ABORTED = 10;
  public static final int OUT_OF_RANGE = 11;
  public static final int UNIMPLEMENTED = 12;
  public static final int UNAVAILABLE = 14;

  /**
   * Creates a new ProtoException with the given message.
   *
   * @param message The error message
   */
  public ProtoException(String message) {
    super(message);
    this.code = UNKNOWN;
  }

  /**
   * Creates a new ProtoException wrapping another exception.
   *
   * @param message The error message
   * @param cause The underlying cause
   */
  public ProtoException(String message, Throwable cause) {
    super(message, cause);
    this.code = UNKNOWN;
  }

  /**
   * Creates a new ProtoException with an error code.
   *
   * @param code The error code (e.g., gRPC status code)
   * @param message The error message
   */
  public ProtoException(int code, String message) {
    super(message);
    this.code = code;
  }

  /**
   * Creates a new ProtoException with an error code and cause.
   *
   * @param code The error code (e.g., gRPC status code)
   * @param message The error message
   * @param cause The underlying cause
   */
  public ProtoException(int code, String message, Throwable cause) {
    super(message, cause);
    this.code = code;
  }

  /**
   * Gets the error code associated with this exception.
   *
   * @return The error code
   */
  public int getCode() {
    return code;
  }

  // Static helper methods for common error scenarios

  /**
   * Creates an error for missing or invalid data (INVALID_ARGUMENT).
   *
   * @param cause The underlying cause, or null
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with INVALID_ARGUMENT code
   */
  public static ProtoException newErrMissingInvalidData(
      Throwable cause, String format, Object... args) {
    return new ProtoException(INVALID_ARGUMENT, String.format(format, args), cause);
  }

  /**
   * Creates an error for resource not found (NOT_FOUND).
   *
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with NOT_FOUND code
   */
  public static ProtoException newErrNotFound(String format, Object... args) {
    return new ProtoException(NOT_FOUND, String.format(format, args));
  }

  /**
   * Creates an error for expired resources or timeouts (DEADLINE_EXCEEDED).
   *
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with DEADLINE_EXCEEDED code
   */
  public static ProtoException newErrExpired(String format, Object... args) {
    return new ProtoException(DEADLINE_EXCEEDED, String.format(format, args));
  }

  /**
   * Creates an error for authentication failures (UNAUTHENTICATED).
   *
   * @param cause The underlying cause, or null
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with UNAUTHENTICATED code
   */
  public static ProtoException newErrUnauthorized(Throwable cause, String format, Object... args) {
    return new ProtoException(UNAUTHENTICATED, String.format(format, args), cause);
  }

  /**
   * Creates a general internal error (INTERNAL).
   *
   * @param cause The underlying cause, or null
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with INTERNAL code
   */
  public static ProtoException newErrGeneral(Throwable cause, String format, Object... args) {
    return new ProtoException(INTERNAL, String.format(format, args), cause);
  }

  /**
   * Creates an error for permission denied (PERMISSION_DENIED).
   *
   * @param cause The underlying cause, or null
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with PERMISSION_DENIED code
   */
  public static ProtoException newErrPermissionDenied(
      Throwable cause, String format, Object... args) {
    return new ProtoException(PERMISSION_DENIED, String.format(format, args), cause);
  }

  /**
   * Creates an error for resources that already exist (ALREADY_EXISTS).
   *
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with ALREADY_EXISTS code
   */
  public static ProtoException newErrAlreadyExists(String format, Object... args) {
    return new ProtoException(ALREADY_EXISTS, String.format(format, args));
  }

  /**
   * Creates an error for resource exhaustion (RESOURCE_EXHAUSTED).
   *
   * @param format Format string for the error message
   * @param args Format arguments
   * @return ProtoException with RESOURCE_EXHAUSTED code
   */
  public static ProtoException newErrResourceExhausted(String format, Object... args) {
    return new ProtoException(RESOURCE_EXHAUSTED, String.format(format, args));
  }

  /**
   * Checks if an exception is a ProtoException with the given error code.
   *
   * @param ex The exception to check
   * @param code The expected error code
   * @return true if the exception is a ProtoException with the given code
   */
  public static boolean hasCode(Throwable ex, int code) {
    if (ex instanceof ProtoException) {
      return ((ProtoException) ex).getCode() == code;
    }
    return false;
  }

  /**
   * Gets the error code from a ProtoException, or UNKNOWN if not a ProtoException.
   *
   * @param ex The exception to extract the code from
   * @return The error code, or UNKNOWN
   */
  public static int extractCode(Throwable ex) {
    if (ex instanceof ProtoException) {
      return ((ProtoException) ex).getCode();
    }
    return UNKNOWN;
  }

  /**
   * Converts a gRPC StatusRuntimeException into a ProtoException. Extracts the gRPC status code and
   * description from the StatusRuntimeException.
   *
   * @param e the gRPC StatusRuntimeException
   * @return a ProtoException with the gRPC status code
   */
  public static ProtoException fromGrpcError(io.grpc.StatusRuntimeException e) {
    int code = e.getStatus().getCode().value();
    String message = e.getStatus().getDescription();
    if (message == null || message.isEmpty()) {
      message = e.getMessage();
    }
    return new ProtoException(code, message, e);
  }
}
